import{z as s,x as o,o as B,c as l,q as t,j as A,D as a,d as r,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"可视化的诊断","description":"","frontmatter":{"title":"可视化的诊断","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bf-visual-diagnostics.md","filePath":"quant/bf-visual-diagnostics.md","lastUpdated":1791063341000}'),p={name:"quant/bf-visual-diagnostics.md"};function d(D,E,u,h,f,m){const e=o("Mermaid");return B(),l("div",null,[E[2]||(E[2]=t('<h1 id="可视化的诊断" tabindex="-1">可视化的诊断 <a class="header-anchor" href="#可视化的诊断" aria-label="Permalink to &quot;可视化的诊断&quot;">​</a></h1><div class="epigraph"><p>图的诚信在于它从哪里来：从重算状态画的图是二手证词，从落盘事件流画的图才是账本的投影。</p><footer>—— 据 Tufte, The Visual Display of Quantitative Information, 1983 对图形诚信的论述；对照生产监控的看板实践整理</footer></div><p><a href="/quant/bf-parallel-backtest">上一课</a>让扫描在集群上跑完，结果库里躺满净值路径；怎么把它们看进人眼而不骗过人眼，是本课。诊断不是策略写完后的装饰，而是框架的一等 API：面板定义与引擎同版本发布，每张图从记录器的事件流重放生成（见<a href="/quant/bf-event-driven-anatomy">事件驱动框架的解剖</a>），因此任何一张图都能用试验身份复现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随手画图的毛病有两类。一类是账对不上：画图的人重新算一遍净值，与引擎账本差在复权、汇率折算或未成交订单上，于是出现两张真相——讨论变成对着两条曲线互相猜。另一类是眼睛先于协议：看到回撤再挑窗口，看到失灵的年份再换切片，<a href="/quant/multitest-discipline-cap">多重检验纪律的现场用法</a>警告过的选择偏差，在看板这一步无声地回来。扫描结果更危险：几千条路径里总有一条最好看，画哪条本身就是一次选择。</p><h3 id="面板族与它们的出处" tabindex="-1">面板族与它们的出处 <a class="header-anchor" href="#面板族与它们的出处" aria-label="Permalink to &quot;面板族与它们的出处&quot;">​</a></h3><p>诊断面板按问题分族，每族钉死出处与口径。<strong>净值族</strong>：时间加权净值对基准，回撤叠加；长历史用对数轴；有申赎的组合区分时间加权与资金加权，见<a href="/quant/twr-vs-mwr">时间加权对资金加权</a>与<a href="/quant/drawdown-calmar">最大回撤与 Calmar</a>。<strong>风险族</strong>：滚动波动、滚动夏普、换手率、敞口热图（资产乘时间）。<strong>成交族</strong>：逐笔决策价对到达价的分布按场所与时段切开，完成率与拒单率随时间——口径接<a href="/quant/slippage-attribution">滑点归因</a>。<strong>事件族</strong>：把停牌、竞价、公司行动叠加回时间轴，让异常日期有名字而不是有尖峰。<strong>扫描族</strong>：样本内外散点、参数面热图、PBO 路径分布。</p>',7)),(B(),A(n,null,{default:a(()=>[i(e,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ES%5B%22%E7%BB%93%E6%9E%9C%E5%BA%93%20%E4%BA%8B%E4%BB%B6%E6%B5%81%E6%8C%89%E8%AF%95%E9%AA%8C%E8%BA%AB%E4%BB%BD%E5%AD%98%E6%A1%A3%22%5D%20--%3E%20RP%5B%22%E9%87%8D%E6%94%BE%E5%99%A8%20%E8%AF%BB%E6%B5%81%E4%B8%8D%E9%87%8D%E7%AE%97%22%5D%0A%20%20RP%20--%3E%20P1%5B%22%E5%87%80%E5%80%BC%E6%97%8F%20%E5%AF%B9%E6%95%B0%E8%BD%B4%20%E5%9B%9E%E6%92%A4%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20RP%20--%3E%20P2%5B%22%E9%A3%8E%E9%99%A9%E6%97%8F%20%E6%BB%9A%E5%8A%A8%E4%B8%8E%E6%95%9E%E5%8F%A3%E7%83%AD%E5%9B%BE%22%5D%0A%20%20RP%20--%3E%20P3%5B%22%E6%88%90%E4%BA%A4%E6%97%8F%20%E5%86%B3%E7%AD%96%E5%AF%B9%E5%88%B0%E8%BE%BE%E4%BB%B7%22%5D%0A%20%20RP%20--%3E%20P4%5B%22%E4%BA%8B%E4%BB%B6%E6%97%8F%20%E5%81%9C%E7%89%8C%E7%AB%9E%E4%BB%B7%E5%8F%A0%E5%8A%A0%E6%97%B6%E9%97%B4%E8%BD%B4%22%5D%0A%20%20RP%20--%3E%20P5%5B%22%E6%89%AB%E6%8F%8F%E6%97%8F%20%E6%95%A3%E7%82%B9%E4%B8%8E%E5%8F%82%E6%95%B0%E9%9D%A2%22%5D%0A%20%20P1%20--%3E%20RD%7B%22%E7%AA%97%E5%8F%A3%E4%B8%8E%E5%88%87%E7%89%87%E6%98%AF%E5%90%A6%E5%85%88%E4%BA%8E%E7%9C%8B%E5%9B%BE%E5%86%BB%E7%BB%93%22%7D%0A%20%20RD%20--%3E%7C%E5%90%A6%7C%20PR%5B%22%E5%85%88%E5%86%BB%E7%BB%93%E5%8D%8F%E8%AE%AE%20%E5%86%8D%E8%AF%BB%E5%9B%BE%22%5D%0A%20%20RD%20--%3E%7C%E6%98%AF%7C%20CON%5B%22%E7%BB%93%E8%AE%BA%E8%BF%9B%E5%85%A5%E8%AE%B0%E5%BD%95%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>操作纪律三条。第一，窗口与切片协议先于看图冻结：要看哪个时段、按什么切（年度、波动制度、流动性分层）、看哪几个面板，写进试验记录再打开图——这与<a href="/quant/hypothesis-preregistration">假设与预注册</a>同一精神，只是发生在可视化层。第二，两张图以上的比较必须同轴同口径：对数轴对对数轴，净额对毛额分开标注，成本情景写进标题。第三，诊断图接受假设、不接受结论：面板的产出是「这段值得查」的候选，查证回到账本与事件流，见<a href="/quant/research-postmortem">复盘与案例写作</a>。</p><p><span class="marginnote">权益曲线用对数轴不是审美：线性轴上前期回撤永远「看起来小」，只因为净值基数小；同一策略在 2020 年的 30% 回撤与 2015 年的 30% 回撤，对数轴上才一样高。基线效应是图形说谎最安静的一种。</span></p><p><span class="marginnote">术语翻译：「协议先于看图冻结」就是先写下「我要看 2018 至 2023、按年度切、看净值与换手两块面板」，存进试验记录，然后才打开图。先看后选，眼睛会替你挑好看的窗口——这与调参数到数据好看是同一种过拟合，只是发生在视觉层。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>「从事件流画图」的机制价值在可审计：图上的每个点能追溯到记录器里的某一行——这笔成交、这次拒单、这条修订。于是诊断从「看形状」升级为「查证据」：异常尖峰点开就是事件列表，两层净值的差异可以按成交假设逐项分解成图（<a href="/quant/bf-vectorized-vs-event">向量化与事件驱动的取舍</a>的对拍协议在这里可视化）。面板定义与框架同版本，则图与账本的漂移在发布层被拦住；研究笔记里的临时图可以存在，但不进报告，报告只收版本化面板。</p>',6)),(B(),A(n,null,{default:a(()=>[i(e,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20SP%5B%22%E5%9B%BE%E4%B8%8A%E5%BC%82%E5%B8%B8%E5%B0%96%E5%B3%B0%22%5D%20--%3E%20CK%7B%22%E8%AF%A5%E7%AA%97%E5%8F%A3%E5%8D%8F%E8%AE%AE%E5%B7%B2%E5%86%BB%E7%BB%93%3F%22%7D%0A%20%20CK%20--%3E%7C%22%E5%90%A6%22%7C%20ST%5B%22%E5%9B%9E%E5%8E%BB%E5%85%88%E5%86%BB%E7%BB%93%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20CK%20--%3E%7C%22%E6%98%AF%22%7C%20DL%5B%22%E7%82%B9%E5%BC%80%E5%BD%93%E6%97%A5%E4%BA%8B%E4%BB%B6%E5%88%97%E8%A1%A8%22%5D%0A%20%20DL%20--%3E%20E1%5B%22%E6%88%90%E4%BA%A4%E4%B8%8E%E6%8B%92%E5%8D%95%E8%AE%B0%E5%BD%95%22%5D%0A%20%20DL%20--%3E%20E2%5B%22%E6%95%B0%E6%8D%AE%E4%BF%AE%E8%AE%A2%E4%B8%8E%E5%85%AC%E5%8F%B8%E8%A1%8C%E5%8A%A8%22%5D%0A%20%20E1%20--%3E%20EX%7B%22%E8%B4%A6%E6%9C%AC%E8%83%BD%E8%A7%A3%E9%87%8A%3F%22%7D%0A%20%20E2%20--%3E%20EX%0A%20%20EX%20--%3E%7C%22%E8%83%BD%22%7C%20DOC%5B%22%E6%A0%87%E6%B3%A8%E4%B8%BA%E5%B7%B2%E8%A7%A3%E9%87%8A%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20EX%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20BUG%5B%22%E5%80%99%E9%80%89%E7%BC%BA%E9%99%B7%20%E8%BF%9B%E5%A4%8D%E7%9B%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p><span class="marginnote">直觉类比：图上每个点能追溯到账本某一行，就像每个快递包裹都有单号——点开能看到揽收、转运、签收的全链路。没有单号的图只是装饰画：尖峰解释不了、分歧对不了账，讨论只能停在「看起来不对劲」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>看板不做审计：审计读账本，不看图。面板数量本身是风险——二十块面板总有几块在某个窗口里好看，眼睛的多重检验比网格更难计数，所以协议冻结比面板裁剪更重要。3D、动画、双轴叠图按 Tufte 的标准默认禁止：它们增加的观感多于信息。最后，诊断面板服务内部研究；对外报告的业绩图另有合规口径，不要把内部诊断截图直接外发。</p><p><span class="marginnote">为什么协议比面板数量更根本：二十块面板里总有几块恰好在某个窗口好看，而人眼每天扫过的「选择次数」不会写进任何试验计数——它却是真实的多重检验。冻结的是看图的人，不是图的数量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>图从记录器的事件流重放生成，不用重算状态；每张图可用试验身份复现。</li><li>五族面板：净值、风险、成交、事件、扫描；口径与出处随面板定义版本化。</li><li>窗口与切片协议先于看图冻结；诊断产出假设，查证回到账本与事件流。</li><li>对数轴、同轴对比、事件叠加是三条默认；双轴与 3D 默认禁止。</li><li>出处：Tufte, <em>The Visual Display of Quantitative Information</em>, 1983；站内<a href="/quant/slippage-attribution">滑点归因</a>、<a href="/quant/twr-vs-mwr">时间加权对资金加权</a>、<a href="/quant/multitest-discipline-cap">多重检验纪律的现场用法</a>各课。</li></ul>',6))])}const _=s(p,[["render",d]]);export{C as __pageData,_ as default};
